const ETAPA_ALV = ['deferido', 'expedido', 'levantado', 'repassado'], NOME_ALV = { deferido: 'Alvará deferido', expedido: 'Alvará expedido', levantado: 'Valor levantado', repassado: 'Repassado ao cliente' };
